<?php

namespace MongoDB\Driver;

use MongoDB\BSON\Serializable;
use stdClass;

/**
 * <div id="class.mongodb-driver-readconcern" class="reference"> <h1 class="title">The MongoDB\Driver\ReadConcern class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.1.0)</p>  <div class="section" id="mongodb-driver-readconcern.intro">   <h2 class="title">简介</h2>   <p class="simpara">    <span class="classname"><strong class="classname">MongoDB\Driver\ReadConcern</strong></span> controls the level of    isolation for read operations for replica sets and replica set shards. This    option requires MongoDB 3.2 or later.   </p>  </div>  <div class="section" id="mongodb-driver-readconcern.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\ReadConcern</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-serializable.php" class="interfacename">MongoDB\BSON\Serializable</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>    <div class="fieldsynopsis">     <span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php#mongodb-driver-readconcern.props.level">\$<var class="varname">level</var></a></var>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php#mongodb-driver-readconcern.constants.linearizable"><var class="varname">AVAILABLE</var></a></var><span class="initializer"> = "available"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php#mongodb-driver-readconcern.constants.linearizable"><var class="varname">LINEARIZABLE</var></a></var><span class="initializer"> = "linearizable"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php#mongodb-driver-readconcern.constants.local"><var class="varname">LOCAL</var></a></var><span class="initializer"> = "local"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php#mongodb-driver-readconcern.constants.majority"><var class="varname">MAJORITY</var></a></var><span class="initializer"> = "majority"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php#mongodb-driver-readconcern.constants.snapshot"><var class="varname">SNAPSHOT</var></a></var><span class="initializer"> = "snapshot"</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-readconcern.bsonserialize.php" class="methodname" style="color:#CC7832">bsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-readconcern.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$level</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-readconcern.getlevel.php" class="methodname" style="color:#CC7832">getLevel</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-readconcern.isdefault.php" class="methodname" style="color:#CC7832">isDefault</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>   }</div>  </div>  <div class="section" id="mongodb-driver-readconcern.props">   <h2 class="title">属性</h2>   <dl>         <dt id="mongodb-driver-readconcern.props.level"><var class="varname">level</var></dt>     <dd>      <span class="simpara">       The read concern level. <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if no level was specified.      </span>     </dd>       </dl>  </div>  <div class="section" id="mongodb-driver-readconcern.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="mongodb-driver-readconcern.constants.available"><strong><span>{@link MongoDB\Driver\ReadConcern::AVAILABLE}</span></strong></dt>     <dd>      <span class="simpara">       Default for reads against secondaries when       <span class="literal">afterClusterTime</span>and <span class="literal">level</span> are       unspecified.      </span>      <span class="simpara">       The query returns the instance's most recent data. Provides no       guarantee that the data has been written to a majority of the replica set       members (i.e. may be rolled back).      </span>      <span class="simpara">       For unsharded collections (including collections in a standalone       deployment or a replica set deployment), <span class="literal">"local"</span> and       <span class="literal">"available"</span> read concerns behave identically.      </span>      <span class="simpara">       For a sharded cluster, <span class="literal">"available"</span> read concern       provides greater tolerance for partitions since it does not wait to       ensure consistency guarantees. However, a query with       <span class="literal">"available"</span> read concern may return orphan documents       if the shard is undergoing chunk migrations since the       <span class="literal">"available"</span> read concern, unlike       <span class="literal">"local"</span> read concern, does not contact the       shard's primary nor the config servers for updated metadata.      </span>     </dd>             <dt id="mongodb-driver-readconcern.constants.linearizable"><strong><span>{@link MongoDB\Driver\ReadConcern::LINEARIZABLE}</span></strong></dt>     <dd>      <span class="simpara">       The query returns data that reflects all successful writes issued with a       write concern of <span class="literal">"majority"</span> <em>and</em>       acknowledged prior to the start of the read operation. For replica sets       that run with <span class="literal">writeConcernMajorityJournalDefault</span> set       to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, linearizable read concern returns data that will never be       rolled back.      </span>      <span class="simpara">       With <span class="literal">writeConcernMajorityJournalDefault</span> set to       <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>, MongoDB will not wait for <span class="literal">w: "majority"</span>       writes to be durable before acknowledging the writes. As such,       <span class="literal">"majority"</span> write operations could possibly roll back       in the event of a loss of a replica set member.      </span>      <span class="simpara">       You can specify linearizable read concern for read operations on the       primary only.      </span>      <span class="simpara">       Linearizable read concern guarantees only apply if read       operations specify a query filter that uniquely identifies a single       document.      </span>      <div class="tip"><strong class="tip">小技巧</strong>       <p class="simpara">        Always use <span class="literal">maxTimeMS</span> with linearizable read concern        in case a majority of data bearing members are unavailable.        <span class="literal">maxTimeMS</span> ensures that the operation does not block        indefinitely and instead ensures that the operation returns an error if        the read concern cannot be fulfilled.       </p>      </div>      <span class="simpara">       Linearizable read concern requires MongoDB 3.4.      </span>     </dd>             <dt id="mongodb-driver-readconcern.constants.local"><strong><span>{@link MongoDB\Driver\ReadConcern::LOCAL}</span></strong></dt>     <dd>      <span class="simpara">       Default for reads against primary if <span class="literal">level</span> is       unspecified and for reads against secondaries if <span class="literal">level</span>       is unspecified but <span class="literal">afterClusterTime</span> is specified.      </span>      <span class="simpara">       The query returns the instance's most recent data. Provides no       guarantee that the data has been written to a majority of the replica set       members (i.e. may be rolled back).      </span>     </dd>             <dt id="mongodb-driver-readconcern.constants.majority"><strong><span>{@link MongoDB\Driver\ReadConcern::MAJORITY}</span></strong></dt>     <dd>      <span class="simpara">       The query returns the instance's most recent data acknowledged as       having been written to a majority of members in the replica set.      </span>      <span class="simpara">       To use read concern level of <span class="literal">"majority"</span>, replica sets       must use WiredTiger storage engine and election protocol version 1.      </span>     </dd>             <dt id="mongodb-driver-readconcern.constants.snapshot"><strong><span>{@link MongoDB\Driver\ReadConcern::SNAPSHOT}</span></strong></dt>     <dd>      <span class="simpara">       Read concern <span class="literal">"snapshot"</span> is available for       multi-document transactions, and starting in MongoDB 5.0, certain read       operations outside of multi-document transactions.      </span>      <span class="simpara">       If the transaction is not part of a causally consistent session, upon       transaction commit with write concern <span class="literal">"majority"</span>, the       transaction operations are guaranteed to have read from a snapshot of       majority-committed data.      </span>      <span class="simpara">       If the transaction is part of a causally consistent session, upon       transaction commit with write concern <span class="literal">"majority"</span>, the       transaction operations are guaranteed to have read from a snapshot of       majority-committed data that provides causal consistency with the       operation immediately preceding the transaction start.      </span>      <span class="simpara">       Outside of multi-document transactions, read concern       <span class="literal">"snapshot"</span> is available on primaries and secondaries       for the following read operations: <span class="literal">find</span>,       <span class="literal">aggregate</span>, and <span class="literal">distinct</span> (on       unsharded collections). All other read commands prohibit       <span class="literal">"snapshot"</span>.      </span>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>PECL mongodb 2.3.0</td>       <td>        Added public <span class="modifier">readonly</span> properties.       </td>      </tr>      <tr>       <td>PECL mongodb 1.11.0</td>       <td>        <span class="simpara">         Added the <strong><span>{@link MongoDB\Driver\ReadConcern::SNAPSHOT}</span></strong>         constant.        </span>       </td>      </tr>      <tr>       <td>PECL mongodb 1.7.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span>.       </td>      </tr>      <tr>       <td>PECL mongodb 1.4.0</td>       <td>        <span class="simpara">         Added the <strong><span>{@link MongoDB\Driver\ReadConcern::AVAILABLE}</span></strong>         constant.        </span>       </td>      </tr>      <tr>       <td>PECL mongodb 1.2.0</td>       <td>        <span class="simpara">         Added the         <strong><span>{@link MongoDB\Driver\ReadConcern::LINEARIZABLE}</span></strong>         constant.        </span>        <span class="simpara">         Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-serializable.php" class="interfacename">MongoDB\BSON\Serializable</a></span>.        </span>       </td>      </tr>     </tbody>       </table>  </div>  <div class="section" id="mongodb-driver-readconcern.seealso">   <h2 class="title">参见</h2>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/read-concern/" class="link external">»&nbsp;Read Concern reference</a></li>  </ul>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\ReadConcern::bsonSerialize} — Returns an object for BSON serialization</li><li>{@link MongoDB\Driver\ReadConcern::__construct} — Create a new ReadConcern</li><li>{@link MongoDB\Driver\ReadConcern::getLevel} — Returns the ReadConcern's "level" option</li><li>{@link MongoDB\Driver\ReadConcern::isDefault} — Checks if this is the default read concern</li></ul></div>
 * 
 * MongoDB\Driver\ReadConcern controls the level of isolation for read operations for replica sets and replica set shards. This option requires the WiredTiger storage engine and MongoDB 3.2 or later.
 * @link https://php.net/manual/zh/class.mongodb-driver-readconcern.php
 * @since 1.1.0
 */
final class ReadConcern implements Serializable
{
    /**
     * @since 1.2.0
     */
    public const LINEARIZABLE = 'linearizable';
    public const LOCAL = 'local';
    public const MAJORITY = 'majority';

    /**
     * @since 1.4.0
     */
    public const AVAILABLE = 'available';

    /**
     * @since 1.11.0
     */
    public const SNAPSHOT = 'snapshot';

    /**
     * @since 2.3.0
     */
    public readonly string|null $level;

    /**
 * <div id="mongodb-driver-readconcern.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ReadConcern::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ReadConcern::__construct</span> — <span class="dc-title">Create a new ReadConcern</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-readconcern.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ReadConcern::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$level</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div>  <p class="simpara">   Constructs a new <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php" class="classname">MongoDB\Driver\ReadConcern</a></span>, which is   an immutable value object.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-readconcern.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">level</span></dt>    <dd>     <span class="simpara">      The <a href="https://www.mongodb.com/docs/manual/reference/read-concern/#read-concern-levels" class="link external">»&nbsp;read concern level</a>.      You may use, but are not limited to, one of the      <a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php#mongodb-driver-readconcern.constants" class="link">class constants</a>.     </span>    </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-readconcern.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-readconcern.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ReadConcern::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #FF8000">// Unspecified read isolation level (uses the server's default behavior) <br></span><span style="color: #9876AA">\$rc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Request read isolation from a single replica set node <br></span><span style="color: #9876AA">\$rc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">::</span><span style="color: #9876AA">LOCAL</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Request read isolation from a majority of the replica set nodes <br></span><span style="color: #9876AA">\$rc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">::</span><span style="color: #9876AA">MAJORITY</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-readconcern.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/read-concern/" class="link external">»&nbsp;Read Concern reference</a></li>  </ul> </div></div>
 * 
     * Construct immutable ReadConcern
     * @link https://php.net/manual/zh/mongodb-driver-readconcern.construct.php
     */
    final public function __construct(?string $level = null) {}


    public static function __set_state(array $properties) {}

    /**
 * <div id="mongodb-driver-readconcern.getlevel" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ReadConcern::getLevel</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ReadConcern::getLevel</span> — <span class="dc-title">Returns the ReadConcern's "level" option</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-readconcern.getlevel-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ReadConcern::getLevel</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-readconcern.getlevel-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-readconcern.getlevel-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the ReadConcern's "level" option.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-readconcern.getlevel-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-readconcern.getlevel-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ReadConcern::getLevel()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$rc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getLevel</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$rc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">::</span><span style="color: #9876AA">LOCAL</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getLevel</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$rc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">::</span><span style="color: #9876AA">MAJORITY</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getLevel</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">NULL<br>string(5)&nbsp;"local"<br>string(8)&nbsp;"majority"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-readconcern.getlevel-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/read-concern/" class="link external">»&nbsp;Read Concern reference</a></li>  </ul> </div></div>
