    /**
 * <div id="mongodb-driver-readconcern.bsonserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ReadConcern::bsonSerialize</h1>  <p class="verinfo">(mongodb &gt;=1.2.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ReadConcern::bsonSerialize</span> — <span class="dc-title">Returns an object for BSON serialization</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-readconcern.bsonserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ReadConcern::bsonSerialize</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-readconcern.bsonserialize-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-readconcern.bsonserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an object for serializing the ReadConcern as BSON.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-readconcern.bsonserialize-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-readconcern.bsonserialize-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ReadConcern::bsonSerialize()</strong></span> with empty read concern</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$rc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">;<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">());<br><br>echo </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rc</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(stdClass)#2&nbsp;(0)&nbsp;{<br>}<br><br>{&nbsp;}</blockquote></div>   </div>  </div><div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ReadConcern::bsonSerialize()</strong></span> with local read concern</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$rc </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadConcern</span><span style="color: #007700">::</span><span style="color: #9876AA">LOCAL</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rc</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">());<br><br>echo </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rc</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(stdClass)#2&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["level"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"local"<br>}<br><br>{&nbsp;"level"&nbsp;:&nbsp;"local"&nbsp;}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-readconcern.bsonserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Serializable::bsonSerialize()} - Provides an array or document to serialize as BSON</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/read-concern/" class="link external">»&nbsp;Read Concern reference</a></li>  </ul> </div></div>
 * 
